        "code": "class ValidationErrors extends Error {\n  #errors = [];\n  \n  constructor(errors) {\n    super(\"Валидация не пройдена\");\n    this.name = \"ValidationErrors\";\n    this.#errors = errors;\n  }\n  \n  get errors() { return [...this.#errors]; }\n  get first() { return this.#errors[0]; }\n  \n  add(field, message) {\n    this.#errors.push({ field, message });\n  }\n}"
